    'kverm33h': {
      'en':
          'Exceptional service from start to finish! The team was professional, transparent about pricing, and made the entire buying process seamless. My BMW was exactly as described and in perfect condition.',
      'af':
          'Uitsonderlike diens van begin tot einde! Die span was professioneel, deursigtig oor pryse en het die hele koopproses naatloos gemaak. My BMW was presies soos beskryf en in perfekte toestand.',
      'ar':
          'خدمة استثنائية من البداية إلى النهاية! كان الفريق محترفًا وشفافًا بشأن الأسعار، وجعل عملية الشراء بأكملها سلسة. سيارتي BMW كانت مطابقة تمامًا للوصف وفي حالة ممتازة.',
      'da':
          'Enestående service fra start til slut! Teamet var professionelt, transparent omkring priser og gjorde hele købsprocessen problemfri. Min BMW var præcis som beskrevet og i perfekt stand.',
      'de':
          'Hervorragender Service von Anfang bis Ende! Das Team war professionell, transparent in Bezug auf die Preise und hat den gesamten Kaufprozess reibungslos gestaltet. Mein BMW entsprach exakt der Beschreibung und war in einwandfreiem Zustand.',
      'es':
          '¡Un servicio excepcional de principio a fin! El equipo fue profesional, transparente con los precios e hizo que todo el proceso de compra fuera perfecto. Mi BMW era exactamente como se describía y estaba en perfectas condiciones.',
      'fr':
          'Un service exceptionnel du début à la fin ! L’équipe était professionnelle, transparente sur les prix et a rendu l’ensemble du processus d’achat extrêmement facile. Ma BMW était conforme à la description et en parfait état.',
      'hi':
          'शुरू से अंत तक बेहतरीन सेवा! टीम पेशेवर थी, कीमतों के बारे में पूरी पारदर्शिता बरती और खरीदारी की पूरी प्रक्रिया को आसान बना दिया। मेरी BMW बिल्कुल वैसी ही थी जैसा बताया गया था और एकदम सही हालत में थी।',
      'it':
          'Servizio eccezionale dall\'inizio alla fine! Il team è stato professionale, trasparente sui prezzi e ha reso l\'intero processo di acquisto impeccabile. La mia BMW era esattamente come descritta e in perfette condizioni.',
      'ja':
          '最初から最後まで素晴らしいサービスでした！スタッフはプロフェッショナルで、価格設定も明確で、購入プロセス全体がスムーズに進みました。私のBMWは説明通りで、完璧な状態でした。',
      'nl':
          'Uitstekende service van begin tot eind! Het team was professioneel, transparant over de prijzen en zorgde ervoor dat het hele aankoopproces vlekkeloos verliep. Mijn BMW was precies zoals beschreven en in perfecte staat.',
      'sv':
          'Exceptionell service från början till slut! Teamet var professionellt, transparent med prissättningen och gjorde hela köpprocessen smidig. Min BMW var exakt som beskriven och i perfekt skick.',
      'tr':
          'Baştan sona olağanüstü hizmet! Ekip profesyoneldi, fiyatlandırma konusunda şeffaftı ve tüm satın alma sürecini sorunsuz hale getirdi. BMW\'m tam olarak tarif edildiği gibiydi ve mükemmel durumdaydı.',
      'ur':
          'شروع سے آخر تک غیر معمولی سروس! ٹیم پیشہ ورانہ تھی، قیمتوں کے بارے میں شفاف تھی، اور اس نے خریداری کے پورے عمل کو بغیر کسی رکاوٹ کے بنایا تھا۔ میری BMW بالکل ویسا ہی تھا جیسا کہ بیان کیا گیا ہے اور بہترین حالت میں ہے۔',
      'zh_Hans': '从始至终，服务都非常出色！团队专业、价格透明，整个购买过程顺畅无阻。我的宝马车与描述完全一致，车况完美。',
      'zh_Hant': '從頭到尾，服務都非常出色！團隊專業、價格透明，整個購買過程順暢無阻。我的BMW車與描述完全一致，車況完美。',
    },
