      'en':
          'With over 8 years of experience in luxury  Vehicle, Sarah specializes in premium  Vehicle and commercial investments. She has successfully closed over 200+ deals worth \$50M+ and maintains long-term relationships with clients through exceptional service and market expertise.',
      'af':
          'Met meer as 8 jaar ondervinding in luukse voertuie, spesialiseer Sarah in premium voertuie en kommersiële beleggings. Sy het suksesvol meer as 200 transaksies ter waarde van \$50 miljoen+ gesluit en handhaaf langtermynverhoudings met kliënte deur middel van uitsonderlike diens en markkundigheid.',
      'ar':
          'تتمتع سارة بخبرة تزيد عن ثماني سنوات في مجال السيارات الفاخرة، وهي متخصصة في استثمارات السيارات المتميزة والتجارية. وقد أنجزت بنجاح أكثر من 200 صفقة بقيمة تزيد عن 50 مليون دولار، وتحافظ على علاقات طويلة الأمد مع عملائها من خلال تقديم خدمة استثنائية وخبرة واسعة في السوق.',
      'da':
