      'de':
          'Mit über acht Jahren Erfahrung im Luxusfahrzeugbereich ist Sarah auf Premiumfahrzeuge und gewerbliche Investitionen spezialisiert. Sie hat bereits über 200 Transaktionen mit einem Volumen von über 50 Millionen US-Dollar erfolgreich abgeschlossen und pflegt durch exzellenten Service und umfassende Marktkenntnisse langfristige Kundenbeziehungen.',
      'es':
          'Con más de 8 años de experiencia en vehículos de lujo, Sarah se especializa en vehículos premium e inversiones comerciales. Ha cerrado con éxito más de 200 transacciones por valor de más de \$50 millones y mantiene relaciones a largo plazo con sus clientes gracias a su excepcional servicio y conocimiento del mercado.',
      'fr':
          'Forte de plus de huit ans d\'expérience dans le secteur automobile de luxe, Sarah se spécialise dans les véhicules haut de gamme et les investissements commerciaux. Elle a mené à bien plus de 200 transactions d\'une valeur supérieure à 50 millions de dollars et entretient des relations durables avec ses clients grâce à un service exceptionnel et une expertise pointue du marché.',
      'hi':
          'लक्जरी वाहनों के क्षेत्र में 8 वर्षों से अधिक के अनुभव के साथ, सारा प्रीमियम वाहनों और वाणिज्यिक निवेशों में विशेषज्ञता रखती हैं। उन्होंने 50 मिलियन डॉलर से अधिक मूल्य के 200 से अधिक सौदे सफलतापूर्वक पूरे किए हैं और असाधारण सेवा और बाजार विशेषज्ञता के माध्यम से ग्राहकों के साथ दीर्घकालिक संबंध बनाए रखती हैं।',
      'it':
          'Con oltre 8 anni di esperienza nel settore dei veicoli di lusso, Sarah è specializzata in investimenti in veicoli premium e commerciali. Ha concluso con successo oltre 200 accordi per un valore di oltre 50 milioni di dollari e mantiene relazioni a lungo termine con i clienti attraverso un servizio eccezionale e una profonda conoscenza del mercato.',
      'ja':
          '高級車業界で8年以上の経験を持つサラは、プレミアムカーおよび商業施設への投資を専門としています。彼女は200件以上の5,000万ドル以上の取引を成功させており、卓越したサービスと市場専門知識を通じてクライアントとの長期的な関係を維持しています。',
      'nl':
          'Met meer dan 8 jaar ervaring in luxe voertuigen is Sarah gespecialiseerd in premium auto\'s en commerciële investeringen. Ze heeft met succes meer dan 200 deals afgerond met een totale waarde van meer dan \$50 miljoen en onderhoudt langdurige relaties met klanten door middel van uitzonderlijke service en marktkennis.',
      'sv':
          'Med över 8 års erfarenhet av lyxfordon är Sarah specialiserad på investeringar i premiumfordon och kommersiella företag. Hon har framgångsrikt avslutat över 200 affärer värda över 50 miljoner dollar och upprätthåller långsiktiga relationer med kunder genom exceptionell service och marknadsexpertis.',
      'tr':
          'Lüks araç sektöründe 8 yılı aşkın deneyime sahip olan Sarah, premium araç ve ticari yatırımlar konusunda uzmanlaşmıştır. 50 milyon doların üzerinde değere sahip 200\'den fazla işlemi başarıyla sonuçlandırmış ve olağanüstü hizmet ve piyasa uzmanlığı sayesinde müşterileriyle uzun vadeli ilişkiler kurmuştur.',
      'ur':
          'لگژری وہیکل میں 8 سال سے زیادہ کے تجربے کے ساتھ، سارہ پریمیم وہیکل اور تجارتی سرمایہ کاری میں مہارت رکھتی ہے۔ اس نے \$50M+ کے 200+ سے زیادہ سودے کامیابی کے ساتھ بند کیے ہیں اور غیر معمولی سروس اور مارکیٹ کی مہارت کے ذریعے کلائنٹس کے ساتھ طویل مدتی تعلقات برقرار رکھے ہوئے ہیں۔',
      'zh_Hans':
          'Sarah拥有超过8年的豪华车行业经验，专注于高端车辆和商业投资。她已成功完成200多笔交易，总价值超过5000万美元，并通过卓越的服务和专业的市场知识与客户保持着长期合作关系。',
