          '• الاستفسارات العامة: خلال ٢٤ ساعة\n\n• المشاكل التقنية: خلال ١٢ ساعة\n\n• مسائل العقارات العاجلة: خلال ٤ ساعات\n\n• حالات الطوارئ: اتصل بخطنا الساخن على الرقم (٥٥٥) ١٢٣-HELP',
      'da':
          '• Generelle forespørgsler: Inden for 24 timer\n• Tekniske problemer: Inden for 12 timer\n• Hastere vedrørende ejendom: Inden for 4 timer\n• Nødsituationer: Ring til vores hotline på (555) 123-HELP',
      'de':
          '• Allgemeine Anfragen: Innerhalb von 24 Stunden\n\n• Technische Probleme: Innerhalb von 12 Stunden\n\n• Dringende Immobilienangelegenheiten: Innerhalb von 4 Stunden\n\n• Notfälle: Rufen Sie unsere Hotline unter (555) 123-HELP an',
      'es':
          '• Consultas generales: En 24 horas\n• Problemas técnicos: En 12 horas\n• Asuntos urgentes relacionados con la propiedad: En 4 horas\n• Emergencias: Llame a nuestra línea directa al (555) 123-HELP',
      'fr':
          '• Renseignements généraux : sous 24 h\n\n• Problèmes techniques : sous 12 h\n\n• Urgences immobilières : sous 4 h\n\n• Urgences : appelez notre ligne d’assistance au (555) 123-HELP',
      'hi':
          '• सामान्य पूछताछ: 24 घंटे के भीतर\n• तकनीकी समस्याएं: 12 घंटे के भीतर\n• संपत्ति संबंधी अत्यावश्यक मामले: 4 घंटे के भीतर\n• आपातकालीन स्थिति: हमारी हेल्पलाइन (555) 123-HELP पर कॉल करें',
      'it':
          '• Richieste generali: entro 24 ore\n• Problemi tecnici: entro 12 ore\n• Questioni immobiliari urgenti: entro 4 ore\n• Problemi di emergenza: chiama la nostra hotline al numero (555) 123-HELP',
      'ja':
          '• 一般的なお問い合わせ：24時間以内\n• 技術的な問題：12時間以内\n• 緊急の不動産関連事項：4時間以内\n• 緊急の問題：ホットライン (555) 123-HELP までお電話ください',
      'nl':
          '• Algemene vragen: binnen 24 uur\n• Technische problemen: binnen 12 uur\n• Spoedeisende zaken met betrekking tot onroerend goed: binnen 4 uur\n• Noodgevallen: bel onze hotline op (555) 123-HELP',
      'sv':
          '• Allmänna förfrågningar: Inom 24 timmar\n• Tekniska problem: Inom 12 timmar\n• Brådskande fastighetsärenden: Inom 4 timmar\n• Akuta problem: Ring vår hotline på (555) 123-HELP',
      'tr':
          '• Genel sorular: 24 saat içinde\n• Teknik sorunlar: 12 saat içinde\n• Acil emlak konuları: 4 saat içinde\n• Acil durumlar: (555) 123-HELP numaralı yardım hattımızı arayın',
      'ur':
          '• عام پوچھ گچھ: 24 گھنٹے کے اندر\n• تکنیکی مسائل: 12 گھنٹے کے اندر\n• فوری جائیداد کے معاملات: 4 گھنٹے کے اندر\nہنگامی مسائل: ہماری ہاٹ لائن (555) 123-HELP پر کال کریں۔',
      'zh_Hans':
          '• 一般咨询：24小时内回复\n\n• 技术问题：12小时内回复\n\n• 紧急房产事宜：4小时内回复\n\n• 紧急情况：请拨打我们的热线电话 (555) 123-HELP',
      'zh_Hant':
          '• 一般諮詢：24小時內回复\n\n• 技術問題：12小時內回复\n\n• 緊急房產事宜：4小時內回复\n\n• 緊急情況：請撥打我們的專線電話 (555) 123-HELP',
    },
